/// own mulligan while both are open.
fn own_prompt(state: &GameState, seat: PlayerId) -> Option<&PendingChoice> {
    state
        .pending
        .as_ref()
        .or_else(|| mulligan_prompt_for(state, seat))
        .filter(|pending| pending.player_id == seat)
}
