// ---------------------------------------------------------------------------------------------
// R2691000: the seat's own library as its owner was shown it
// ---------------------------------------------------------------------------------------------

mod r2691000_own_library_as_its_owner_was_shown {
    use super::*;

    /// R2691000: a card of the seat's own library changed after it went in redacts to the face its
    /// owner was shown; one shown Radiant as it went in (a Radiant Created copy shuffled in openly) stays so.
    #[test]
    fn r2691000_a_known_own_library_card_redacts_to_the_face_its_owner_was_shown() {
        let mut a = clone(&real_game("observe-r2691000"));
        let secret = a.players[AI].library[0].id.clone();
        let open = a.players[AI].library[1].id.clone();
        {
            let card = find_instance_mut(&mut a, &secret).expect("the secret card");
            card.radiant = false;
            card.known_as = Some(KnownAs { def_id: card.def_id.clone(), radiant: false });
            card.cost_mod = -1; // #95's discount, made inside the library
        }
        {
            let card = find_instance_mut(&mut a, &open).expect("the open card");
            card.radiant = true;
            card.created = Some(true);
            card.known_as = Some(KnownAs { def_id: card.def_id.clone(), radiant: true });
        }
        let mut b = clone(&a);
        // #42's roll, made inside the library: the record stays.
        find_instance_mut(&mut b, &secret).expect("the secret card").radiant = true;

        let hidden = hidden_instance_ids(&b, AI);
        assert!(!hidden.contains(&secret) && !hidden.contains(&open));
        assert_ne!(hash_state(&a), hash_state(&b));
        assert_eq!(hash_state(&redact(&a, AI)), hash_state(&redact(&b, AI)));

        let known = card_by_id(&a, &secret).and_then(|card| card.known_as.clone());
        let public = redact(&b, AI);
        let shown = card_by_id(&public, &secret).expect("the secret card");
        assert!(!shown.radiant);
        assert_eq!(shown.cost_mod, 0);
        assert_eq!(shown.known_as, known);
        assert_eq!(Some(shown.def_id.clone()), known.map(|known| known.def_id));
        let kept = card_by_id(&public, &open).expect("the open card");
        assert!(kept.radiant);
        assert_eq!(kept.created, Some(true));
        assert_eq!(kept.known_as.as_ref().map(|known| known.radiant), Some(true));
    }

    /// R2691000: after Eugenics (#42) resolves, the AI's decision on a fixed seed is the same whatever
    /// its rolls made Radiant in the AI's own library.
    #[test]
    fn r2691000_after_eugenics_the_ais_decision_is_the_same_whatever_its_rolls_made_radiant() {
        jackioh_cards::register_all();
        let library = vec!["core-025"; 20]; // cost 4: Eugenics exiles none
        let mut s = scenario(json!({
            "seed": "observe-r2691000-eugenics",
            "p1": { "hand": ["core-042", "core-005"], "library": library },
            "p2": { "hand": ["core-005"] },
        }));
        s.play("core-042", json!({}));
        let rolled = s.state().clone();
        assert!(rolled.pending.is_none());
        assert_eq!(rolled.players[AI].library.len(), 20);
        let mut none = clone(&rolled);
        let mut all = clone(&rolled);
        none.players[AI].library.iter_mut().for_each(|card| card.radiant = false);
        all.players[AI].library.iter_mut().for_each(|card| card.radiant = true);
        assert!(all.players[AI].library.iter().all(|card| card.known_as.as_ref().is_some_and(|known| !known.radiant)));
        assert_ne!(hash_state(&none), hash_state(&all));
        assert_eq!(hash_state(&redact(&none, AI)), hash_state(&redact(&all, AI)));
        let from_none = decide(&none, AI, &mut ai_options("observe-r2691000-eugenics", AI_BUDGET));
        assert!(from_none.is_some());
        assert_eq!(decide(&all, AI, &mut ai_options("observe-r2691000-eugenics", AI_BUDGET)), from_none);
    }

    /// R2691000, §10.8: a card the seat's own prompt reveals out of its library (#51) keeps the face the
    /// prompt shows; one it does not offer reads as its owner was shown it.
    #[test]
    fn r2691000_a_library_card_the_seats_own_prompt_offers_keeps_the_face_the_prompt_shows() {
        jackioh_cards::register_all();
        let mut s = scenario(json!({
            "seed": "observe-r2691000-tutor",
            "p1": { "hand": ["core-051"], "library": ["core-025", "core-025", "core-025", "core-008", "core-005"] },
            "p2": { "hand": ["core-005"] },
        }));
        s.play("core-051", json!({}));
        s.answer(json!("Unit"));
        s.answer(json!("4+"));
        let mut state = s.state().clone();
        let offered: Vec<String> = state
            .pending
            .as_ref()
            .filter(|pending| pending.player_id == AI)
            .map(|pending| {
                pending
                    .options
                    .iter()
                    .filter_map(|option| match &option.selection {
                        Selection::Instance { instance_id } => Some(instance_id.clone()),
                        _ => None,
                    })
                    .collect()
            })
            .unwrap_or_default();
        assert_eq!(offered.len(), 3);
        let vanilla = state.players[AI]
            .library
            .iter()
            .find(|card| card.def_id == "core-008")
            .map(|card| card.id.clone())
            .expect("Mr. Vanilla");
        for id in [&offered[0], &vanilla] {
            find_instance_mut(&mut state, id).expect("a library card").radiant = true;
        }
        let public = redact(&state, AI);
        assert_eq!(card_by_id(&public, &offered[0]).map(|card| card.radiant), Some(true));
        assert_eq!(card_by_id(&public, &vanilla).map(|card| card.radiant), Some(false));
    }
}
```
   If `cargo fmt` reflows this code, accept its output. The test names hold the token `r2691000`, which `spec check` requires.

8. **Run the new tests and the whole crate.** Run `cargo test -p jackioh-ai r2691000`, then `cargo test -p jackioh-ai`.
   - **Only if** `b12_readable_cards_survive_determinization_in_real_mid_game_states_from_both_seats` fails on a card in the seat's own library, update that test. A random game changed that card inside the library, and the seat may no longer read the change. In `determinize_b12`, add this helper:
     ```rust
     /// R2691000: a card of `seat`'s own library reads as its owner was shown it, unless its own prompt offers it.
     fn shown_to(state: &GameState, card: &CardInstance, seat: PlayerId) -> CardInstance {
         let mut shown = card.clone();
         let offered = state.pending.as_ref().is_some_and(|pending| {
             pending.player_id == seat
                 && pending.options.iter().any(|option| matches!(&option.selection, Selection::Instance { instance_id } if *instance_id == card.id))
         });
         if card.zone == (Zone::Library { player: seat }) && !offered && let Some(known) = &card.known_as {
             shown.def_id = known.def_id.clone();
             shown.radiant = known.radiant;
             shown.damage = 0;
             shown.buffs = AttackHealth { attack: 0, health: 0 };
         }
         shown
     }
     ```
     Then compare `readable(after)` with `readable(&shown_to(state, card, seat))` in that test only, and record this in the notes.
   - Any other failure is a real regression. Report it; do not weaken any test.

## Tests

All in `crates/ai/tests/ai/observe.rs`:
- `r2691000_a_known_own_library_card_redacts_to_the_face_its_owner_was_shown`: an in-library Radiant roll (plus a discount) leaves the redacted hash unchanged; the card reads base with `cost_mod` 0 and keeps its record; a card recorded Radiant and Created keeps both.
- `r2691000_after_eugenics_the_ais_decision_is_the_same_whatever_its_rolls_made_radiant`: after a real Eugenics resolution, the "none Radiant" and "all Radiant" outcomes give the same full `Decision`, `stats.score` included. Stockpile's draws make the score depend on the drawn faces, so this test fails without step 2.
- `r2691000_a_library_card_the_seats_own_prompt_offers_keeps_the_face_the_prompt_shows`: an offered card keeps its live Radiant; a card that is not offered loses it.

Commands, in order:
1. `cargo test -p jackioh-ai r2691000`
2. `cargo test -p jackioh-ai` (includes `redact_twice`, `redact_view_mirror`, B10/B12, `lethal_hint`, `pinned`)
3. `cargo clippy -p jackioh-ai --all-targets -- -D warnings`
4. `cargo fmt --check`
5. `cargo jackioh spec check`, `cargo jackioh catalog check`, `cargo jackioh patches check`
6. `cargo jackioh classify --base origin/main --claims`: expect kind `ai` and no fragment needed.
7. `cargo jackioh gate`, smoke size, once. Report its summary lines whatever they say; tune nothing.

## Done when

- [ ] Known own-library cards redact from `known_as` plus Created; R312 cards are still placeholders; offered cards keep their live face; library order is unchanged.
- [ ] The three R2691000 tests pass, and `cargo test -p jackioh-ai` is green (or step 8's single sanctioned B12 update is made and recorded).
- [ ] R2691000.md, pending/2691.md, the §9.9 sentence, R312's sentence and the README agree.
- [ ] clippy, rustfmt, spec, catalog and patches checks are green. The gate's result is reported. No diff under `apps/web/src/wire`.
- [ ] The notes record each decision taken here (the prompt exception, R312 rather than §10.8, forgetting a change seen before re-entry) and the alternative rejected for each.

## Risks

- **Hidden information.** Restoring anything from the live card besides `created` would leak the change again. Restore only from the cloned `KnownAs`.
- **Prompt reveals.** If a card offered by the seat's own prompt is reset, `view_for` of the AI's world differs from the true view (B10) and the AI misjudges its pick. The `offered` skip and the third test cover this.
- **Idempotency.** The training arena and `decide` redact a state that is already redacted (SURFACE §14.1). The pass keeps `known_as`, so a second run gives the same result; `redact_twice.rs` checks it.
- **Determinism and replay.** The pass draws nothing and only edits the clone. `determinize` still shuffles the own library and samples only placeholders.
- **Strength.** The AI loses knowledge of in-library changes that R311 says its seat never had. The gate's smoke run is the check; report it rather than tune anything.

## Open questions

None. R2691000 is the first free number in #2691's block. The spec (R310–R312, R943, §10.8's option rule) settles what the seat may read.
